CustomField.formula:
IF(ISBLANK( SBQQ__Quote__r.SBQQ__EndDate__c )= FALSE, SBQQ__Quote__r.SBQQ__EndDate__c, DATE( /*YEAR*/ YEAR( EffectiveDate ) + FLOOR((MONTH(EffectiveDate) + SBQQ__Quote__r.SBQQ__SubscriptionTerm__c -1)/12),
/*MONTH*/ CASE(MOD(MONTH(EffectiveDate) + SBQQ__Quote__r.SBQQ__SubscriptionTerm__c,12), 0, 12, MOD(MONTH(EffectiveDate)+ SBQQ__Quote__r.SBQQ__SubscriptionTerm__c,12)),
/*DAY*/ MIN(DAY(EffectiveDate), CASE(MOD(MONTH(EffectiveDate) + SBQQ__Quote__r.SBQQ__SubscriptionTerm__c,12), 9, 30, 4, 30, 6, 30, 11, 30, 2,
/* return max days for February dependent on if end date is leap year */
IF(MOD(YEAR(EffectiveDate) + FLOOR((MONTH(EffectiveDate) + SBQQ__Quote__r.SBQQ__SubscriptionTerm__c)/12), 400) = 0 || (MOD(YEAR(EffectiveDate) + FLOOR((MONTH(EffectiveDate) + SBQQ__Quote__r.SBQQ__SubscriptionTerm__c)/12), 4) = 0 && MOD(YEAR(EffectiveDate) + FLOOR((MONTH(EffectiveDate) + SBQQ__Quote__r.SBQQ__SubscriptionTerm__c)/12), 100) <> 0 ), 29, 28), 31) ) ) - 1 )
